    <script>
        document.addEventListener('change',event=>{if(!event.target.matches('.drop-zone input[type=file]'))return;let name=event.target.files?.[0]?.name;let target=event.target.closest('.drop-zone')?.querySelector('[data-file-name]');if(target&&name)target.textContent=name;});
        (()=>{const button=document.querySelector('.nav-toggle'),close=()=>{document.body.classList.remove('nav-open');button?.setAttribute('aria-expanded','false');},open=()=>{document.body.classList.add('nav-open');button?.setAttribute('aria-expanded','true');};button?.addEventListener('click',()=>document.body.classList.contains('nav-open')?close():open());document.querySelectorAll('[data-nav-close]').forEach(node=>node.addEventListener('click',close));document.addEventListener('keydown',event=>{if(event.key==='Escape')close();});document.querySelector('.side-nav')?.addEventListener('click',event=>{if(event.target.closest('a')&&matchMedia('(max-width:900px)').matches)close();});})();
        document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.table-wrap').forEach(wrap=>{if(wrap.previousElementSibling?.classList.contains('table-scroll-controls'))return;const controls=document.createElement('div');controls.className='table-scroll-controls';controls.innerHTML=`<span>Table columns</span><button type="button" aria-label="Scroll table left">←</button><button type="button" aria-label="Scroll table right">→</button>`;const [left,right]=controls.querySelectorAll('button');wrap.before(controls);const update=()=>{const max=Math.max(0,wrap.scrollWidth-wrap.clientWidth);left.disabled=wrap.scrollLeft<=2;right.disabled=wrap.scrollLeft>=max-2;controls.hidden=max<=2;};const move=direction=>wrap.scrollBy({left:direction*Math.max(220,wrap.clientWidth*.7),behavior:'smooth'});left.addEventListener('click',()=>move(-1));right.addEventListener('click',()=>move(1));wrap.addEventListener('scroll',update,{passive:true});if(window.ResizeObserver)new ResizeObserver(update).observe(wrap);requestAnimationFrame(update);});});
        document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('table').forEach(table=>{const head=table.tHead,body=table.tBodies[0];if(!head||!body||head.querySelector('.table-filter-row'))return;const rows=[...body.rows],sample=rows.find(row=>!row.querySelector('.empty'));if(!sample)return;const intervalOnly=table.classList.contains('interval-table'),currentOnly=table.classList.contains('current-stock-table'),cellCount=sample.cells.length,count=intervalOnly?1:currentOnly?2:cellCount;const labels=[...head.rows[head.rows.length-1].cells].map(cell=>cell.textContent.replace(/\s+/g,' ').trim()),selected=Array.from({length:count},()=>new Set());const filterRow=document.createElement('tr');filterRow.className='table-filter-row';for(let i=0;i<count;i++){const th=document.createElement('th');if(intervalOnly)th.colSpan=cellCount;const values=[...new Set(rows.map(row=>(row.cells[i]?.textContent||'').replace(/\s+/g,' ').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));if(intervalOnly||(currentOnly&&i===0)){const input=document.createElement('input');input.type='search';input.placeholder='Search name';input.setAttribute('aria-label','Search name');input.addEventListener('input',()=>{selected[i].clear();if(input.value.trim())selected[i].add(input.value.trim().toLocaleLowerCase());apply();});th.append(input);}else{const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=i===0?'Search name':'Filter';details.addEventListener('toggle',()=>{if(details.open)document.querySelectorAll('.table-filter-row details[open]').forEach(other=>{if(other!==details)other.open=false;});});const menu=document.createElement('div');menu.className='table-filter-menu';if(i===0){const search=document.createElement('input');search.type='search';search.className='filter-search';search.placeholder='Search options';search.addEventListener('input',()=>menu.querySelectorAll('label').forEach(label=>{label.hidden=!label.textContent.toLocaleLowerCase().includes(search.value.toLocaleLowerCase());}));menu.append(search);}values.forEach(value=>{const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=value;box.addEventListener('change',()=>{box.checked?selected[i].add(value):selected[i].delete(value);summary.textContent=selected[i].size?`${selected[i].size} selected`:i===0?'Search name':'Filter';apply();});label.append(box,document.createTextNode(value));menu.append(label);});details.append(summary,menu);th.append(details);}filterRow.append(th);}head.append(filterRow);function apply(){rows.forEach(row=>{row.hidden=selected.some((set,index)=>set.size&&![...set].every(value=>(row.cells[index]?.textContent||'').replace(/\s+/g,' ').trim().toLocaleLowerCase().includes(value.toLocaleLowerCase())));});}});});
        document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.current-stock-table').forEach(table=>{const filterRow=table.tHead?.querySelector('.table-filter-row'),columnCount=table.tBodies[0]?.rows[0]?.cells.length||0;if(!filterRow)return;while(filterRow.cells.length<columnCount){const spacer=document.createElement('th');spacer.setAttribute('aria-hidden','true');filterRow.append(spacer);}});});
        document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('table[data-spirit-filter]').forEach((table,index)=>{const rows=[...(table.tBodies[0]?.rows||[])].filter(row=>!row.querySelector('.empty'));const types=[...new Set(rows.map(row=>(row.dataset.spiritType||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));if(!types.length)return;const bar=document.createElement('div');bar.className='spirit-filter-bar';bar.setAttribute('role','radiogroup');bar.setAttribute('aria-label','Filter by spirit type');const title=document.createElement('span');title.className='spirit-filter-title';title.textContent='Spirit type';bar.append(title);const group='spirit-filter-'+index;const apply=value=>rows.forEach(row=>row.classList.toggle('spirit-filter-hidden',Boolean(value)&&row.dataset.spiritType!==value));[['All spirits',''],...types.map(type=>[type,type])].forEach(([labelText,value],optionIndex)=>{const label=document.createElement('label');label.className='spirit-filter-option';const input=document.createElement('input');input.type='radio';input.name=group;input.value=value;input.checked=optionIndex===0;input.addEventListener('change',()=>apply(input.value));label.append(input,document.createTextNode(labelText));bar.append(label);});table.parentElement.insertBefore(bar,table);});});
        (()=>{const overlay=document.getElementById('page-loading');if(!overlay)return;let pending=0;const show=()=>{overlay.hidden=false;};const hide=()=>{if(pending<=0)overlay.hidden=true;};window.pegwiseLoading={show,hide};const nativeFetch=window.fetch.bind(window);window.fetch=async(...args)=>{pending++;show();try{return await nativeFetch(...args);}finally{pending--;hide();}};window.addEventListener('beforeunload',show);document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.target==='_blank'||link.hasAttribute('download'))return;const url=new URL(link.href,window.location.href);if(url.origin===window.location.origin&&url.pathname!==window.location.pathname||url.search!==window.location.search)show();});document.addEventListener('submit',event=>{if(event.defaultPrevented)return;show();});})();
    </script>
</body>
